import sys
def solve(n, edges):
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v in edges: adj[u].append(v); adj[v].append(u)
    dp = [[0, 0] for _ in range(n + 1)]
    visited = [False] * (n + 1)
    parent = [0] * (n + 1); post_order = []
    stack = [(1, 0, False)]
    while stack:
        node, p, leaving = stack.pop()
        if leaving: post_order.append(node)
        elif not visited[node]:
            visited[node] = True; parent[node] = p
            stack.append((node, p, True))
            for nb in adj[node]:
                if not visited[nb]: stack.append((nb, node, False))
    for node in post_order:
        dp[node][1] = 1; dp[node][0] = 0
        for nb in adj[node]:
            if nb != parent[node]:
                dp[node][1] += dp[nb][0]
                dp[node][0] += max(dp[nb][0], dp[nb][1])
    return str(max(dp[1][0], dp[1][1]))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    n = int(data[0])
    edges = [(int(data[1+i*2]),int(data[2+i*2])) for i in range(n-1)]
    print(solve(n, edges))

